import json
R,C=30,8
g=[[8]*C for _ in range(R)]
pts=[(1,6),(3,7),(5,0),(5,7),(9,2),(12,2),(12,4),(17,6),(20,7),(21,5)]
for r,c in pts:g[r][c]=7
out=[row[:] for row in g]
for r in range(R):
    xs=[c for rr,c in pts if rr==r]
    if len(xs)>1:
        for c in range(min(xs),max(xs)+1):
            if out[r][c]==8:out[r][c]=3
for c in range(C):
    ys=[r for r,cc in pts if cc==c]
    if len(ys)>1:
        for r in range(min(ys),max(ys)+1):
            if out[r][c]==8:out[r][c]=3
print(json.dumps(out,separators=(',',':')))
print('rows',len(out))
